   assert.equal(args.p_company,COMPANY);assert.equal(args.p_owner,body.sub);const key=args.p_dataset+':'+args.p_owner,expected=state.revisions.get(key)||0;if(args.p_expected!==expected)return{data:null,error:{code:'CONFLICT'}};
   state.writes.push({label,...copy(args)});state.revisions.set(key,expected+1);if(args.p_dataset==='cars')state.cars.set(body.sub,copy(args.p_payload));return{data:expected+1,error:null};
