 f.prompt=async()=>{const modal=page.locator('#session-replacement-modal');await modal.waitFor({state:'visible'});assert((await modal.textContent()).includes(CONFIRM));assert.equal(await modal.getAttribute('aria-modal'),'true');return modal;};
