 const names=['index.html','assets/session-ownership.js','assets/operator-console.js','assets/idle-auth-storage.js','operator.html'],hashes=()=>Object.fromEntries(names.map(file=>[file,crypto.createHash('sha256').update(fs.readFileSync(path.join(ROOT,file))).digest('hex')])),before=hashes();
